/* Baseline (naive) chain allocator for the metadata-floor fixture.
 *
 * The general helper applies CHAIN_FLOOR to every small request.  That is the
 * right policy for chains that carry data inline, and the wrong policy for
 * reference chains whose inline area is never used — which is exactly the
 * opportunity allocation-path-optimization is meant to find.
 *
 * Do not edit this file when optimising: the optimised variant lives in
 * opt/chain_opt.c so both can be built and compared from the same harness.
 */
#include "chain.h"

#include <stdlib.h>
#include <string.h>

/* Next power of two not below CHAIN_FLOOR, or the raw size when it is larger. */
struct chain *
chain_new(size_t size)
{
	struct chain *chain;
	size_t to_alloc;

	if (size > (size_t)-1 - sizeof(struct chain))
		return NULL;
	size += sizeof(struct chain);

	to_alloc = CHAIN_FLOOR;
	while (to_alloc < size)
		to_alloc <<= 1;

	chain = (struct chain *)malloc(to_alloc);
	if (!chain)
		return NULL;
	memset(chain, 0, sizeof(*chain));
	chain->buffer_len = to_alloc - sizeof(struct chain);
	chain->buffer = (unsigned char *)(chain + 1);
	chain->refcnt = 1;
	return chain;
}

static void chain_free(struct chain *chain)
{
	if (!chain)
		return;
	if (chain->flags & CHAIN_REFERENCE) {
		struct chain_ref *info =
		    (struct chain_ref *)((unsigned char *)chain + sizeof(*chain));
		if (info->cleanup)
			info->cleanup(chain->buffer, chain->off, info->extra);
	}
	free(chain);
}

int cbuf_init(struct cbuf *buf)
{
	if (!buf)
		return -1;
	buf->first = buf->last = NULL;
	buf->total_len = 0;
	return 0;
}

void cbuf_free(struct cbuf *buf)
{
	if (!buf)
		return;
	cbuf_clear(buf);
	buf->first = buf->last = NULL;
	buf->total_len = 0;
}

static void cbuf_insert(struct cbuf *buf, struct chain *chain)
{
	chain->next = NULL;
	if (buf->last)
		buf->last->next = chain;
	else
		buf->first = chain;
	buf->last = chain;
	buf->total_len += chain->off;
}

int cbuf_append(struct cbuf *buf, const void *data, size_t len)
{
	struct chain *chain;

	if (!buf || (!data && len))
		return -1;
	/* Data chains may reuse the tail chain when it has room. */
	if (buf->last && !(buf->last->flags & CHAIN_REFERENCE) &&
	    buf->last->off + len <= buf->last->buffer_len) {
		memcpy(buf->last->buffer + buf->last->off, data, len);
		buf->last->off += len;
		buf->total_len += len;
		return 0;
	}
	chain = chain_new(len);
	if (!chain)
		return -1;
	memcpy(chain->buffer, data, len);
	chain->off = len;
	cbuf_insert(buf, chain);
	return 0;
}

int cbuf_add_reference(struct cbuf *buf, const void *data, size_t len,
    void (*cleanup)(const void *, size_t, void *), void *extra)
{
	struct chain *chain;
	struct chain_ref *info;

	if (!buf || (!data && len))
		return -1;
	chain = chain_new(sizeof(struct chain_ref));
	if (!chain)
		return -1;
	chain->flags |= CHAIN_REFERENCE;
	chain->buffer = (unsigned char *)data;
	chain->buffer_len = len;
	chain->off = len;
	info = (struct chain_ref *)((unsigned char *)chain + sizeof(*chain));
	info->cleanup = cleanup;
	info->extra = extra;
	cbuf_insert(buf, chain);
	return 0;
}

int cbuf_drain(struct cbuf *buf, size_t len)
{
	struct chain *chain, *next;

	if (!buf)
		return -1;
	if (len >= buf->total_len) {
		cbuf_clear(buf);
		return 0;
	}
	buf->total_len -= len;
	for (chain = buf->first; chain && len >= chain->off; chain = next) {
		next = chain->next;
		len -= chain->off;
		chain_free(chain);
	}
	buf->first = chain;
	if (chain) {
		chain->buffer += len;
		chain->off -= len;
	} else {
		buf->last = NULL;
	}
	return 0;
}

void cbuf_clear(struct cbuf *buf)
{
	struct chain *chain, *next;

	if (!buf)
		return;
	for (chain = buf->first; chain; chain = next) {
		next = chain->next;
		chain_free(chain);
	}
	buf->first = buf->last = NULL;
	buf->total_len = 0;
}

size_t cbuf_length(const struct cbuf *buf)
{
	return buf ? buf->total_len : 0;
}

const unsigned char *cbuf_data(const struct cbuf *buf)
{
	return (buf && buf->first) ? buf->first->buffer : NULL;
}
